let revealObserver;
function enhanceVisuals(){if(typeof IntersectionObserver==='undefined')return;if(revealObserver)revealObserver.disconnect();revealObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.add('in-view');revealObserver.unobserve(entry.target)}},{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>{el.classList.add('reveal-ready');revealObserver.observe(el)})}
