function jobBadge(){return badge(state.active?'Гарантия активна':state.inspectionSubmitted?'Осмотр на проверке':state.jobSubmitted?'Ожидает осмотра':'Черновик',state.active?'green':state.jobSubmitted?'orange':'')}
const stepRoutes=['job-car','job-panels','job-material','job-prep','job-process','job-final','job-review'];
function wizard(n,title,body){return head('Паспорт установки',title)+`<div class="form-layout"><form class="card" data-form="job-${n}"><div class="step-caption"><span>Шаг ${n} из 7</span><span>${title}</span></div><div class="steps">${stepRoutes.map((_,i)=>`<span class="step ${i<n-1?'done':i===n-1?'current':''}"></span>`).join('')}</div><h2>${title}</h2>${body}<div class="form-bottom">${link('Назад',n===1?'asc':stepRoutes[n-2],'secondary')}<button type="submit" class="btn primary">${n===7?'Передать паспорт на проверку':'Продолжить'}</button></div></form><div class="summary"><h3>DEMO-WARRANTY-01</h3><p>${esc(state.job.car)}<br>${esc(state.job.plate)}</p><div class="rule" style="background:#414651"></div><p>${esc(state.job.owner)}<br>${esc(state.job.service)}<br>${esc(state.job.brand)}</p>${jobBadge()}<div class="rule" style="background:#414651"></div><p>Гарантия активируется после контрольного осмотра и его подтверждения.</p></div></div>`}
define('job-car','A02','Паспорт · автомобиль и участники','Сервисный центр',()=>wizard(1,'Автомобиль и участники',`<div class="grid two">${field('ФИО владельца','owner',state.job.owner)}${field('Телефон владельца','phone',state.job.phone,'tel')}${field('Марка и модель','car',state.job.car)}${field('Госномер','plate',state.job.plate)}${field('VIN','vin',state.job.vin,'text','17 символов')}${field('ФИО мастера','master',state.job.master)}${field('Название АСЦ','center',state.job.center)}${field('Дата установки','date',state.job.date,'date')}</div><label class="check"><input required checked type="checkbox">Владелец согласен на оформление цифрового паспорта и обработку данных</label>`));
const panels=['Капот','Передний бампер','Передние крылья','Зеркала','Крыша','Двери','Задние крылья','Задний бампер','Пороги'];
function bodyMap(){const rects=[['Передний бампер',92,25,116,30],['Капот',99,62,102,75],['Крыша',105,162,90,110],['Задний бампер',92,347,116,27],['Передние крылья',58,65,34,71],['Зеркала',43,142,38,18],['Двери',59,168,36,110],['Задние крылья',59,285,36,56],['Пороги',45,190,10,120]];return `<div class="body-map"><svg viewBox="0 0 300 405" role="img" aria-label="Схема зон оклейки автомобиля, вид сверху"><path d="M90 20 Q60 30 55 85 L55 330 Q65 385 95 390 L205 390 Q235 385 245 330 L245 85 Q240 30 210 20Z" fill="#f8f9fb" stroke="#c0c7d1" stroke-width="2"/><rect x="100" y="140" width="100" height="16" rx="5" fill="#bcc8d6"/><rect x="100" y="279" width="100" height="14" rx="5" fill="#bcc8d6"/>${rects.map(([label,x,y,w,h])=>`<rect tabindex="0" role="button" aria-label="${label}" aria-pressed="${state.panels.includes(label)}" data-panel="${label}" class="panel ${state.panels.includes(label)?'selected':''}" x="${x}" y="${y}" width="${w}" height="${h}" rx="5"/>${['Передние крылья','Зеркала','Двери','Задние крылья','Пороги'].includes(label)?`<rect tabindex="0" role="button" aria-label="${label} справа" aria-pressed="${state.panels.includes(label)}" data-panel="${label}" class="panel ${state.panels.includes(label)?'selected':''}" x="${300-x-w}" y="${y}" width="${w}" height="${h}" rx="5"/>`:''}`).join('')}<text x="150" y="106" text-anchor="middle" class="panel-label" style="fill:${state.panels.includes('Капот')?'#061216':'#bdd4dd'}">Капот</text><text x="150" y="217" text-anchor="middle" class="panel-label" style="fill:${state.panels.includes('Крыша')?'#061216':'#bdd4dd'}">Крыша</text><text x="150" y="402" text-anchor="middle" class="panel-label">Схема · вид сверху</text></svg><div class="grid" style="gap:8px">${panels.map(p=>`<button type="button" data-panel="${p}" class="panel-btn ${state.panels.includes(p)?'selected':''}" aria-pressed="${state.panels.includes(p)}">${state.panels.includes(p)?'✓ ':''}${p}</button>`).join('')}</div></div>`}
define('job-panels','A03','Паспорт · услуга и зоны оклейки','Сервисный центр',()=>wizard(2,'Услуга и зоны оклейки',`<div class="option-grid">${['Частичная','Зоны риска','Полная','Индивидуальная'].map(t=>`<label class="option"><input type="radio" name="service" value="${t}" ${state.job.service===t?'checked':''}>${t}<small>${t==='Полная'?'Все доступные детали':t==='Зоны риска'?'Капот, бампер, крылья и зеркала':'Выберите детали на схеме'}</small></label>`).join('')}</div><div class="rule"></div><p class="muted" style="font-size:14px">Нажмите на деталь или её название. Бирюзовым отмечены выбранные зоны.</p><div id="body-map">${bodyMap()}</div>`));
define('job-material','A04','Паспорт · материал и тубус','Сервисный центр',()=>wizard(3,'Материал и идентификация рулона',`<div class="grid two">${select('Бренд','brand',['ATOMGARD','DETRONA','UNDERCOVER'],state.job.brand)}${field('Серия / SKU','sku',state.job.sku)}${field('Номер тубуса','tube',state.job.tube)}${field('Партия рулона','batch',state.job.batch)}${field('Расход, м','meters',state.job.meters,'number')}</div>${upload('roll','Рулон, этикетка и номер тубуса','Номер должен читаться на фотографии.')}<div class="callout warn" style="margin-top:18px">Расширенная «Гарантия 360» в этом прототипе доступна для ATOMGARD. Условия гарантии остальных брендов требуют отдельного согласования.</div>`));
define('job-prep','A05','Паспорт · подготовка автомобиля','Сервисный центр',()=>wizard(4,'Подготовка автомобиля',`<h3>Проверка до установки</h3><label class="check"><input type="checkbox" name="clean" required ${state.job.clean?'checked':''}>Автомобиль вымыт, поверхность очищена и обезжирена</label><label class="check"><input type="checkbox" name="noObstacles" required ${state.job.noObstacles?'checked':''}>Нет препятствий к нанесению материала</label>${select('Состояние ЛКП','paint',['Заводское покрытие, дефектов не выявлено','Есть перекрашенные элементы','Есть дефекты покрытия'],state.job.paint||'Заводское покрытие, дефектов не выявлено')}<label class="field">Дефекты / согласованные ограничения<textarea name="defects">${esc(state.job.defects||'Видимых препятствий к установке не выявлено.')}</textarea></label>${upload('before','Автомобиль и подготовленные поверхности','Общие виды, детали под оклейку и зафиксированные дефекты.')}<div class="actions" style="margin-top:16px">${button('Заполнить пример фотографий','demo-photos','secondary small','type="button"')}</div>`));
define('job-process','A06','Паспорт · процесс установки','Сервисный центр',()=>wizard(5,'Процесс установки',`${upload('process','Фото процесса оклейки','Зафиксируйте нанесение материала и работу с краями.')}<div class="rule"></div><label class="field">Комментарий мастера<textarea name="processComment">${esc(state.job.processComment||'Материал установлен с соблюдением технологии. Края и стыки проверены.')}</textarea></label><label class="check"><input type="checkbox" name="technology" required ${state.job.technology?'checked':''}>Технология установки соблюдена</label>${button('Заполнить пример фотографий','demo-photos','secondary small','type="button"')}`));
define('job-final','A07','Паспорт · итоговые фотографии','Сервисный центр',()=>wizard(6,'Готовая работа',`${upload('final','Итоговые фотографии','9 фото: 4 общих вида, 4 края и стыка, 1 мастер с автомобилем.')}<div class="rule"></div><div class="grid three"><div><h3>4 общих вида</h3><p class="muted" style="font-size:14px">Спереди, сзади и с двух сторон.</p></div><div><h3>4 детали</h3><p class="muted" style="font-size:14px">Края, углы и стыки материала.</p></div><div><h3>1 мастер</h3><p class="muted" style="font-size:14px">Мастер рядом с автомобилем.</p></div></div>${button('Заполнить пример фотографий','demo-photos','secondary small','type="button"')}`));
define('job-review','A08','Паспорт · проверка и отправка','Сервисный центр',()=>wizard(7,'Проверить паспорт',`<div class="callout">Паспорт создаётся сейчас. Гарантия останется в статусе «Ожидает контрольного осмотра».</div>${table(['Данные','Значение'],[['Владелец',esc(state.job.owner)],['Автомобиль',esc(state.job.car)+' · '+esc(state.job.plate)],['VIN',esc(state.job.vin)],['Мастер / АСЦ',esc(state.job.master)+' / '+esc(state.job.center)],['Услуга',esc(state.job.service)],['Зоны',esc(state.panels.join(', '))],['Материал',esc(state.job.brand)+' / '+esc(state.job.sku)],['Тубус',esc(state.job.tube)],['Фотографии',`Подготовка ${state.photos.before.length} · рулон ${state.photos.roll.length} · процесс ${state.photos.process.length} · результат ${state.photos.final.length}`]])}<label class="check"><input type="checkbox" required checked>Данные паспорта проверены мастером</label>${state.demoPhotos?'<div class="callout warn">Фотографии заполнены демонстрационными отметками. Это пример сценария, а не подтверждение реальной установки.</div>':''}`));
define('job-success','A09','Паспорт · ожидает осмотра','Сервисный центр',()=>success('Паспорт DEMO-WARRANTY-01 создан','Работа зарегистрирована. Гарантия ещё не активна. Следующий шаг — контрольный осмотр в согласованный срок.',link('Контрольный осмотр','inspection','primary')+link('Все работы','asc','secondary')));
define('inspection','A10','Контрольный осмотр','Сервисный центр',()=>head('Контрольный осмотр',state.job.car+' · '+state.job.plate,jobBadge())+(state.jobSubmitted?`<form class="card" data-form="inspection"><div class="grid two">${field('Дата осмотра','inspectionDate','2026-10-08','date')}${field('Мастер','inspectionMaster',state.job.master)}</div>${upload('inspection','Фото контрольного осмотра','Общие виды, края и стыки после стабилизации материала.')}<div class="actions" style="margin-top:16px">${button('Загрузить демо пример осмотра','demo-inspection','secondary small','type="button"')}</div><div class="rule"></div>${select('Результат осмотра','inspectionResult',['Дефектов не выявлено','Требуется исправление'],state.job.inspectionResult||'Дефектов не выявлено')}<label class="field">Комментарий<textarea name="inspectionComment">Края и стыки осмотрены. Отслоений не выявлено.</textarea></label><label class="check"><input type="checkbox" required checked>Контрольный осмотр выполнен, фотографии относятся к этому автомобилю</label><div class="callout">После отправки FIVEROX проверяет осмотр. При подтверждении сертификат активируется автоматически.</div><div class="form-bottom">${link('Все работы','asc','secondary')}<button class="btn primary" type="submit">Отправить осмотр на проверку</button></div></form>`:`<div class="card"><h2>Сначала зарегистрируйте установку</h2><p class="muted">В осмотр передаётся уже оформленный паспорт с фотографиями подготовки и работы.</p>${link('Оформить паспорт','job-car','primary')}</div>`));
define('inspection-success','A11','Осмотр · на проверке','Сервисный центр',()=>success('Осмотр отправлен на проверку','Гарантия пока не активна. В демо можно переключиться в кабинет администратора и проверить материалы.',link('Открыть проверку FIVEROX','admin-quality','primary')+link('Посмотреть сертификат','certificate','secondary')));
function certificate(){return head('Электронный сертификат','DEMO-WARRANTY-01',link('Мои гарантии','client-warranty','secondary'))+`<section class="certificate"><div class="certificate-header"><div><div class="eyebrow">${state.job.brand==='ATOMGARD'?'ГАРАНТИЯ 360':'ГАРАНТИЯ БРЕНДА'}</div><h2>Паспорт защиты автомобиля</h2></div><img src="assets/${state.job.brand.toLowerCase()}.png" alt="${state.job.brand}"></div><div class="rule"></div>${jobBadge()}<dl>${[['Номер', 'DEMO-WARRANTY-01'],['Владелец',state.job.owner],['Автомобиль',state.job.car],['Госномер',state.job.plate],['VIN',state.job.vin],['Материал',state.job.brand+' / '+state.job.sku],['Услуга',state.job.service],['Тубус',state.job.tube],['Мастер',state.job.master],['АСЦ',state.job.center],['Дата установки',state.job.date],['Контрольный осмотр',state.active?'Подтверждён':'Ожидает подтверждения']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p class="muted" style="font-size:14px">Зоны: ${esc(state.panels.join(', '))}</p><div class="callout ${state.active?'good':'warn'}">${state.active?'Гарантия активирована после подтверждения контрольного осмотра.':'Гарантия ещё не активна. Для активации нужен подтверждённый контрольный осмотр.'} Срок и условия определяются правилами выбранного материала. Демонстрационный сертификат не имеет юридической силы.</div><div class="actions">${button('Печать / PDF','print','secondary')}${link('Обратиться по гарантии','claim','primary')}</div></section>`}
define('certificate','A12','Электронный сертификат','Гарантия 360',certificate);
const centerData=[{name:'FIVEROX Studio',district:'Москва · Хорошёвский район',status:'Авторизованный АСЦ',rating:'4,9',reviews:38,authorized:true},{name:'Detail Garage',district:'Москва · Хамовники',status:'Профиль проверен',rating:'4,7',reviews:21,authorized:false},{name:'North Detailing',district:'Москва · Сокол',status:'В каталоге',rating:'4,5',reviews:12,authorized:false}];
function centerCards(filter='all',search=''){return centerData.filter(c=>(filter!=='authorized'||c.authorized)&&c.name.toLowerCase().includes(search.toLowerCase())).map((c,i)=>`<div class="card"><div class="eyebrow">${c.district}</div><h2>${c.name}</h2>${badge(c.status,c.authorized?'green':'')}<div class="rule"></div><div><span class="stars">★★★★★</span> <strong>${c.rating}</strong> <span class="muted">· ${c.reviews} отзывов</span></div><p class="muted" style="font-size:14px;margin:15px 0">${c.authorized?'Защитные плёнки · Гарантия 360 ATOMGARD':'Детейлинг · Условия гарантии уточняйте у центра'}</p>${link('Профиль центра',c.authorized?'center':'center-other','secondary')}</div>`).join('')||'<div class="blank-note">Центры не найдены. Измените поиск.</div>'}
define('centers','C01','Каталог сервисных центров','Сервисные центры',()=>head('Найдите свой центр','Выбирайте по расположению, отзывам и статусу авторизации.')+`<div class="filters"><label class="field">Город<select id="city-filter"><option>Москва</option><option>Все города</option></select></label><label class="field">Название<input id="center-search" placeholder="Название центра"></label><label class="field">Статус<select id="center-filter"><option value="all">Все центры</option><option value="authorized">Только авторизованные АСЦ</option></select></label></div><div class="grid three" id="center-results">${centerCards()}</div><div class="section card"><h3>Три понятных статуса</h3><p class="muted" style="font-size:14px">«В каталоге» — размещён профиль. «Профиль проверен» — данные центра подтверждены. «Авторизованный АСЦ» — центр допущен FIVEROX к программе установки и гарантии.</p></div>`);
function centerProfile(authorized=true){return head(authorized?'FIVEROX Studio':'Detail Garage',authorized?'Москва · Хорошёвский район':'Москва · Хамовники',link('Все центры','centers','secondary'))+`<div class="grid two"><div class="card">${badge(authorized?'Авторизованный АСЦ FIVEROX':'Профиль проверен',authorized?'green':'blue')}<div class="rule"></div><h2>Защита и уход за автомобилем</h2><p class="muted">Антигравийные плёнки, тонировка, подготовка и уход за покрытием.</p><div class="rating-number">${authorized?'4,9':'4,7'}</div><div class="stars">★★★★★</div><p class="muted" style="margin:12px 0">${authorized?'38':'21'} отзывов · демо данные</p><p class="muted" style="font-size:14px">${authorized?'В центре доступна Гарантия 360 для установок ATOMGARD после подтверждённого контрольного осмотра.':'Центр не авторизован для Гарантии 360 ATOMGARD. Условия его услуг и гарантии согласуются отдельно.'}</p>${button('Записаться в центр',authorized?'book-authorized':'book-other','primary')}</div><div><div class="map-placeholder"><svg viewBox="0 0 450 250" role="img" aria-label="Схематичная карта района"><path class="map-road" d="M0 100L450 140M130 0L100 250M330 0L250 250"/><rect class="map-block" x="150" y="25" width="100" height="65" rx="8"/><rect class="map-block" x="140" y="155" width="80" height="70" rx="8"/><rect class="map-block" x="340" y="160" width="80" height="60" rx="8"/><circle class="map-pin" cx="225" cy="125" r="15"/><text class="map-label" x="250" y="112">Центр</text></svg></div><p class="location-note">Схема расположения для прототипа. Реальная карта будет подключена позже.</p><div class="card"><h3>Часы работы</h3><p class="muted">Ежедневно · 10:00–20:00<br>Адрес центра — демо данные</p></div></div></div><div class="section card"><div class="section-head"><h2>Отзывы клиентов</h2>${link('Оставить отзыв','review','secondary')}</div><div class="review"><strong>Алексей · подтверждённая запись</strong><span class="stars">★★★★★</span><p>Объяснили варианты защиты, показали материал и оформили паспорт работ.</p><small class="muted">Пример отзыва для прототипа</small></div>${state.review?'<div class="review"><strong>Ваш отзыв</strong><span class="stars">★★★★★</span><p>'+esc(state.reviewText)+'</p><small class="muted">На модерации · демо</small></div>':''}</div>`}
define('center','C02','Профиль авторизованного АСЦ','Сервисные центры',()=>centerProfile());
define('center-other','C03','Профиль детейлинг-центра','Сервисные центры',()=>centerProfile(false));
define('booking','C04','Запись в сервисный центр','Сервисные центры',()=>head('Запись в '+(state.bookingAuthorized===false?'Detail Garage':'FIVEROX Studio'),'Выберите услугу и удобное время.')+`<form class="card" data-form="booking"><div class="grid two">${select('Услуга','bookingService',['Зоны риска','Полная оклейка','Частичная оклейка','Контрольный осмотр'],'Зоны риска')}${field('Автомобиль','bookingCar',state.job.car)}${field('Дата','bookingDate','2026-10-08','date')}${select('Время','bookingTime',['10:00','12:00','15:00','18:00'],'12:00')}${field('ФИО','bookingName',state.job.owner)}${field('Телефон','bookingPhone',state.job.phone,'tel')}</div><div class="callout">Запись создаёт предварительный заказ. Баллы начисляются после подтверждённой услуги. ${state.bookingAuthorized===false?'Гарантия 360 в этом центре недоступна.':'Сертификат создаётся из оформленной работы; гарантия активируется после принятого контрольного осмотра.'}</div><label class="check"><input type="checkbox" required checked>Согласен на передачу данных выбранному центру</label><div class="form-bottom">${link('Назад','centers','secondary')}<button type="submit" class="btn primary">Подтвердить запись</button></div></form>`);
define('booking-success','C05','Запись · подтверждение','Сервисные центры',()=>success('Запись создана',`${esc(state.job.bookingCar||state.job.car)} · ${esc(state.job.bookingDate||'2026-10-08')} · ${esc(state.job.bookingTime||'12:00')}. Центр подтвердит время. Начисление баллов и активация гарантии на этом этапе не происходят.`,link('Мои записи','client-bookings','primary')+link('Мой кабинет','client','secondary')));
define('review','C06','Отзыв о центре','Сервисные центры',()=>head('Оставить отзыв','Отзыв о подтверждённой услуге проходит модерацию.')+`<form class="card" data-form="review">${select('Оценка','rating',['5 — отлично','4 — хорошо','3 — нормально','2 — плохо','1 — очень плохо'],'5 — отлично')}<label class="field">Ваш опыт<textarea name="reviewText" required>Материал и работу показали, паспорт установки оформили.</textarea></label><div class="form-bottom">${link('Назад','center','secondary')}<button class="btn primary" type="submit">Отправить на модерацию</button></div></form>`);
