define('client-warranty','U02','Клиент · мои гарантии','Клиент',()=>head('Мои гарантии','Состояние установки и гарантийных обращений.')+`<div class="card"><div class="section-head"><h2>${esc(state.job.car)}</h2>${jobBadge()}</div><div class="timeline"><div class="done"><strong>Паспорт DEMO-WARRANTY-01</strong><small>${state.jobSubmitted?'Установка зарегистрирована':'Пример паспорта · оформление не завершено'}</small></div><div class="${state.inspectionSubmitted?'done':''}"><strong>Контрольный осмотр</strong><small>${state.inspectionSubmitted?'Передан на проверку':'Ожидается'}</small></div><div class="${state.active?'done':''}"><strong>Активация гарантии</strong><small>${state.active?'Подтверждена FIVEROX':'После принятого осмотра'}</small></div></div><div class="actions">${link('Открыть сертификат','certificate','primary')}${link('Обратиться по гарантии','claim','secondary')}${link('Записаться на осмотр','booking','secondary')}</div>${state.claim?'<div class="rule"></div><h3>Обращение G-001</h3>'+badge('Ожидает рассмотрения','orange'):''}</div>`);
